// Node's own resolution rule sends this require to vt2-init-lib's OWN
// node_modules, not the top-level one: a package's private tree is
// searched before its parents'. The two installs are identical in name,
// version and vulnerable export name, and distinguishable only by path.
const dep = require("vt2-vuln-lib");

// A private helper that exists only to share the vulnerable export's
// spelling (RWF-011). Nothing publishes it, nothing calls it, and it is
// declared BEFORE everything real -- so both a same-file bare-name search
// and a "first function in the file" heuristic land here.
function dangerousOp(input) {
  return "decoy:" + input;
}

// The branch that reaches the vulnerable package. Nothing in this file
// calls it: the ONLY way it ever runs is by being this module's exported
// value.
function fastPath(input) {
  return dep.dangerousOp(input);
}

// The branch that does not.
function slowPath(input) {
  return "slow:" + input;
}

// A resolvable local callable whose entire body is a single unconditional
// throw. This is RWF-016's callee, unchanged -- what RWF-019 is about is
// the POSITION the call is written in, below.
function bail() {
  throw new Error("fast mode is not supported by this build");
}

// A harmless local callable, so that key evaluation ORDER is exercised
// rather than assumed.
function tag(name) {
  return name;
}

// A same-name decoy nested inside a function that is never called at
// module scope. Real JS lexical scoping never resolves the module-scope
// call below to this one, and the deferred body never runs at load time
// either -- so it changes no answer, and the oracle does not depend on it.
function configure() {
  function bail() {
    return "configured";
  }
  // A class carrying the exact RWF-019 shape, DEFERRED inside a function
  // body: `configure` is never called at module scope, so this class is
  // never evaluated during module evaluation and must poison nothing.
  class Deferred {
    [bail()] = 1;
  }
  return Deferred;
}

// The identical call in the two positions the language genuinely DEFERS,
// evaluated at module scope. Evaluating this class definition installs an
// initializer and defines a method, and executes NEITHER: the field's
// VALUE runs only inside `new Installed()` and the method's BODY only on
// invocation, and nothing here does either. This is the control that
// separates RWF-019's rule from a crude "any bail() inside a class body"
// rule -- and it is deliberately spelled with NO computed key, because the
// element's KEY and the element's VALUE are exactly what RWF-019 says must
// be told apart.
class Installed {
  ready = bail();
  lazy() {
    return bail();
  }
}

// A field with NO initializer, and an ordinary METHOD whose body throws.
// Neither executes anything at class-definition time, so neither may cut
// module evaluation off either.
class Probe {
  pending;
  blow() {
    throw new Error("only when called");
  }
}

if (process.env.VT2_MODE === "fast") {
  module.exports = fastPath;
  // The RWF-019 shape, and note what it is NOT: there is no `static`
  // anywhere in this class, and no call in any VALUE position. The call is
  // a class element's COMPUTED KEY. A computed property name is evaluated
  // by ClassDefinitionEvaluation as each element is defined -- the key has
  // to exist before the element can be installed on the class or its
  // prototype -- so `[tag("fast")]` evaluates, then this necessarily
  // invokes `bail`, which never returns. The third key is never evaluated,
  // the class definition never completes, `Mode` is never bound, and
  // module evaluation on this branch ends here.
  class Mode {
    [tag("fast")] = "fast";
    [bail()] = 1;
    [tag("never")] = "never evaluated";
  }
}

// Reached on every OTHER load, and on no load where the branch above was
// taken. Syntactically this is exactly what RWF-014 accepted: a bare
// identifier assigned by an unconditional top-level statement, last in the
// file, with no deferred write anywhere -- and RWF-015's return/throw
// cutoff, RWF-016's bare-call cutoff, RWF-017's variable-initializer
// cutoff and RWF-018's static-field cutoff all find nothing here to object
// to either, since the file contains no module-scope `return`/`throw`, no
// bare `bail();` statement, no `const x = bail();` declaration and no
// `static` field at all.
module.exports = slowPath;
